export type IataSearchItem = { name: string; type: "city" | "country"; iata?: string; country?: string; aliases?: string[] };

export function getAllSearchableItems(): IataSearchItem[] {
  const items: IataSearchItem[] = [];
  const added = new Set<string>();

  Object.entries(arabicToIata).forEach(([name, iata]) => {
    const key = `city:${name}`;
    if (!added.has(key)) {
      items.push({ name, type: "city", iata });
      added.add(key);
    }
  });

  Object.entries(countries).forEach(([name, data]) => {
    const aliases = Object.entries(searchAliases)
      .filter(([, target]) => target === name)
      .map(([alias]) => alias)
      .filter((alias) => alias !== name);
    const key = `country:${name}`;
    if (!added.has(key)) {
      items.push({
        name,
        type: "country",
        country: data.name,
        aliases: aliases.length > 0 ? aliases : undefined,
      });
      added.add(key);
    }
  });

  return items;
}

export function getCountryIata(countryName: string): string | null {
  const normalized = countryName.trim().toLowerCase();
  const aliasTarget = searchAliases[normalized];
  const country = countries[countryName] || (aliasTarget ? countries[aliasTarget] : undefined) || Object.entries(countries).find(([name]) => name.toLowerCase() === normalized)?.[1];
  return country?.cities[0]?.iata || null;
}

export function getCityName(iataCode: string): string {
  return iataToCityName[iataCode.trim().toUpperCase()] || iataCode;
}

export function getIataCode(cityName: string): string {
  const normalized = cityName.trim().toLowerCase();

  const directCityIata = arabicToIata[normalized];
  if (directCityIata) return directCityIata;

  const aliasTarget = searchAliases[normalized];
  if (aliasTarget) {
    const country = countries[aliasTarget];
    if (country) return country.cities[0]?.iata || cityName;
    const cityIata = arabicToIata[aliasTarget.toLowerCase()];
    if (cityIata) return cityIata;
  }

  const directCountry = countries[cityName] || Object.entries(countries).find(([name]) => name.toLowerCase() === normalized)?.[1];
  if (directCountry) return directCountry.cities[0]?.iata || cityName;

  const englishMatch = Object.entries(iataToCityName).find(([, name]) => name.toLowerCase() === normalized);
  if (englishMatch) return englishMatch[0];

  if (/^[A-Z]{3}$/i.test(normalized)) {
    return normalized.toUpperCase();
  }

  return cityName;
}

